INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (150, 177, 'PVDC coating film -K film (BOPP/BOPA/BOPET film coated PVDC)', '../upload/image/20180826/20180826131125_93877.jpg', '<p></p><p>PVDC coating film -K film (BOPP/BOPA/BOPET film coated PVDC)</p> <p>1 Types for PVDC coating film -K film<br/> PVDC coating film -K film (BOPP/BOPA/BOPET film coated PVDC)<br/> KOPP (BOPP film, coated on both sides heat sealing barrier PVDC coating)<br/> KPA (BOPA film, coated on both sides heat sealing barrier PVDC coating)<br/> KPET (BOPET film, coated on both sides heat sealing barrier PVDC coating)<br/> KPE (PE film, coated on both sides heat sealing barrier PVDC coating)<br/> Thickness of PVDC coating film: 12UM (for KPET),21UM (for KOPP),17UM (for KPA)...<br/> Width of PVDC coating film: 120-1500MM Length: 200-4000M Inner core:1" 2" 3" 6". <br/> 2 Features of PVDC coating film -K film (BOPP/BOPA/BOPET film coated PVDC)<br/> a. excellent gas barrier properties, excellent in fragrance preservation property<br/> b. excellent low-temperature heat-sealing properties, sealing and smoothing seed<br/> very good transparent performance<br/> 3 main purposes for PVDC coating film -K film (BOPP/BOPA/BOPET film coated PVDC):<br/> a. cigarette packaging b snack packaging c. dessert packaging</p>', '2026-09-06 20:58:45');
